  const send = (method, params = {}) => new Promise(resolve => { const n = ++id; pending.set(n, resolve); ws.send(JSON.stringify({id:n, method, params})); });
  const evaluate = async expression => (await send('Runtime.evaluate', {expression, awaitPromise:true, returnByValue:true})).result.result.value;
  await send('Page.enable'); await send('Runtime.enable');
  await send('Page.navigate', {url:'http://127.0.0.1:8765'});
  for (let i=0; i<60; i++) { await sleep(500); const ready=await evaluate("!!document.querySelector('#bladeToggle') && !!document.querySelector('.step-item')"); if(ready) break; }
  const initial = await evaluate("({checked:document.querySelector('#bladeToggle').getAttribute('aria-checked'),state:document.querySelector('.blade-power-state').textContent, canvas:!!document.querySelector('.scene-wrap canvas'), steps:[...document.querySelectorAll('.step-item')].map(x=>x.textContent.trim())})");
  const toggle = async () => { await evaluate("document.querySelector('#bladeToggle').click()"); return evaluate("({checked:document.querySelector('#bladeToggle').getAttribute('aria-checked'),state:document.querySelector('.blade-power-state').textContent})"); };
  const on=await toggle(), off=await toggle();
  const stepCount=await evaluate("document.querySelectorAll('.step-item').length");
  const bladeIndex=await evaluate("[...document.querySelectorAll('.step-item')].findIndex(x=>x.textContent.toLowerCase().includes('blade'))");
  const autoOn=await evaluate(`document.querySelector('[data-step="${bladeIndex}"]').click(); document.querySelectorAll('.option-card')[1].click(); ({step:document.querySelector('.step-summary').textContent,checked:document.querySelector('#bladeToggle').getAttribute('aria-checked')})`);
  const userChoice=await evaluate("document.querySelector('#bladeToggle').click(); document.querySelector('[data-step=\"0\"]').click(); ({step:document.querySelector('.step-summary').textContent,checked:document.querySelector('#bladeToggle').getAttribute('aria-checked')})");
  console.log(JSON.stringify({initial,on,off,stepCount,bladeIndex,autoOn,userChoice}, null, 2));
  ws.close();
})().catch(e=>{console.error(e);process.exit(1)});
